--
-- Struktur dari tabel `data_bendungan`
--

CREATE TABLE `data_bendungan` (
  `id_bendungan` int NOT NULL,
  `id_pos` int NOT NULL COMMENT 'FK ke master_pos (hanya bendungan)',
  `id_user` int DEFAULT NULL COMMENT 'FK ke users (petugas yang input)',
  `id_manual` int DEFAULT NULL COMMENT 'FK ke data_manual (opsional)',
  `tanggal_input` date NOT NULL COMMENT 'Tanggal pengukuran',
  `nwl` float DEFAULT NULL COMMENT 'Normal Water Level (m)',
  `nwl_volume` float DEFAULT NULL COMMENT 'Volume max normal (jt.m³)',
  `nwl_luas` float DEFAULT NULL COMMENT 'Luas max normal (km²)',
  `rain` float DEFAULT NULL COMMENT 'Curah hujan (mm)',
  `elevasi` float DEFAULT NULL COMMENT 'Elevasi muka air aktual (m)',
  `volume` float DEFAULT NULL COMMENT 'Volume tampungan aktual (jt.m³)',
  `luas` float DEFAULT NULL COMMENT 'Luas genangan aktual (km²)',
  `inflow` float DEFAULT NULL COMMENT 'Debit masuk (m³/s)',
  `pltm` float DEFAULT NULL COMMENT 'Debit PLTM (m³/s)',
  `spillway` float DEFAULT NULL COMMENT 'Debit spillway (m³/s)',
  `total_outflow` float DEFAULT NULL COMMENT 'Total outflow (m³/s)',
  `plta_status` enum('on','off','maintenance') DEFAULT NULL COMMENT 'Status PLTA',
  `irigasi_status` enum('on','off','maintenance') DEFAULT NULL COMMENT 'Status irigasi',
  `tail_water` varchar(50) DEFAULT NULL COMMENT 'Tail water',
  `rembesan_vnotch_h` float DEFAULT NULL COMMENT 'Tinggi air di V-Notch (cm)',
  `rembesan_vnotch_q` float DEFAULT NULL COMMENT 'Debit V-Notch (lt/s)',
  `rembesan_pump_pit_l_h` float DEFAULT NULL COMMENT 'Tinggi air Pump Pit Kiri (cm)',
  `rembesan_pump_pit_l_q` float DEFAULT NULL COMMENT 'Debit Pump Pit Kiri (lt/s)',
  `rembesan_pump_pit_r_h` float DEFAULT NULL COMMENT 'Tinggi air Pump Pit Kanan (cm)',
  `rembesan_pump_pit_r_q` float DEFAULT NULL COMMENT 'Debit Pump Pit Kanan (lt/s)',
  `keterangan` text,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Jam input otomatis',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `tahun_mulai_pembangunan` year DEFAULT NULL COMMENT 'Tahun mulai pembangunan',
  `tipe_bendungan` varchar(100) DEFAULT NULL COMMENT 'Tipe bendungan',
  `elevasi_mercu` float DEFAULT NULL COMMENT 'Elevasi mercu (mdpl)',
  `luas_das` float DEFAULT NULL COMMENT 'Luas Daerah Aliran Sungai (km²)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Data parameter lengkap bendungan';

