--
-- Struktur dari tabel `data_irigasi`
--

CREATE TABLE `data_irigasi` (
  `id_irigasi` int NOT NULL,
  `kode_integrasi` varchar(50) DEFAULT NULL,
  `nama_aset` varchar(200) NOT NULL,
  `jenis_daerah_irigasi` varchar(50) DEFAULT NULL,
  `kode_identifikasi` varchar(50) DEFAULT NULL,
  `status_sumber_data` varchar(100) DEFAULT NULL,
  `unit_kerja` varchar(200) DEFAULT NULL,
  `wilayah_sungai` varchar(100) DEFAULT NULL,
  `daerah_aliran_sungai` varchar(100) DEFAULT NULL,
  `kewenangan` varchar(50) DEFAULT NULL,
  `lintas_kewenangan` varchar(50) DEFAULT NULL,
  `tahun_data` varchar(20) DEFAULT NULL,
  `bangunan_pengambilan` text,
  `status_pemeliharaan` varchar(50) DEFAULT NULL,
  `di_op_kan_oleh` varchar(50) DEFAULT NULL,
  `deskripsi_aset` text,
  `keterangan_tambahan` text,
  `status_data` varchar(50) DEFAULT NULL,
  `status_verifikasi` varchar(50) DEFAULT NULL,
  `provinsi` varchar(100) DEFAULT NULL,
  `kabupaten_kota` varchar(200) DEFAULT NULL,
  `kecamatan` varchar(200) DEFAULT NULL,
  `kelurahan` text,
  `latitude` decimal(11,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `keterangan_lokasi` text,
  `luas_permen` float DEFAULT NULL,
  `luas_baku` float DEFAULT NULL,
  `luas_potensial` float DEFAULT NULL,
  `luas_fungsional` float DEFAULT NULL,
  `jenis_bangunan_utama` varchar(100) DEFAULT NULL,
  `nama_bangunan_utama_bendungan` varchar(200) DEFAULT NULL,
  `nama_bangunan_utama_bendung` varchar(200) DEFAULT NULL,
  `nama_bangunan_utama_free_intake` varchar(200) DEFAULT NULL,
  `sumber_air` varchar(200) DEFAULT NULL,
  `luas_tangkapan_hujan` float DEFAULT NULL,
  `jenis_rawa` varchar(50) DEFAULT NULL,
  `fungsi_jaringan_irigasi` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Data Daerah Irigasi';

