INSERT INTO `data_irigasi` (`id_irigasi`, `kode_integrasi`, `nama_aset`, `jenis_daerah_irigasi`, `kode_identifikasi`, `status_sumber_data`, `unit_kerja`, `wilayah_sungai`, `daerah_aliran_sungai`, `kewenangan`, `lintas_kewenangan`, `tahun_data`, `bangunan_pengambilan`, `status_pemeliharaan`, `di_op_kan_oleh`, `deskripsi_aset`, `keterangan_tambahan`, `status_data`, `status_verifikasi`, `provinsi`, `kabupaten_kota`, `kecamatan`, `kelurahan`, `latitude`, `longitude`, `keterangan_lokasi`, `luas_permen`, `luas_baku`, `luas_potensial`, `luas_fungsional`, `jenis_bangunan_utama`, `nama_bangunan_utama_bendungan`, `nama_bangunan_utama_bendung`, `nama_bangunan_utama_free_intake`, `sumber_air`, `luas_tangkapan_hujan`, `jenis_rawa`, `fungsi_jaringan_irigasi`, `created_at`, `updated_at`) VALUES
(1, '06.09.11518016434', 'D.I. Bumi Agung', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'TULANG BAWANG', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Intake Bendung Way Bumi Agung', 'Sudah', 'Pusat', 'Hingga 2025, D.I. Way Bumi Agung baru dibangun sampai BBA 18 dari dari rencana total 42 BBA sesuai dengan skema jaringan D.I. Bumi Agung. Sedangkan jaringan DI Bumi Agung dari BBA.4b sampai BBA.18 Eksisting belum berfungsi karena terjadi longsoran pada bangunan BBA 4b. Tahun 2025 dilakukan rehabilitasi saluran untuk memfungsikan kembali.\n\nBelum dibangun saluran sekunder di DI Way Bumi Agung.', '-', 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG UTARA', 'Tersebar**', 'Tersebar**; Cempedak; Hujan Mas; Sri Jaya; Sri Agung; Cempaka; Cempaka Barat', -4.85180000, 104.73827500, 'Lokasi Daerah Irigasi Way Bumi Agung meliputi 4 kecamatan yang berada di Kabupaten Lampung Utara yaitu Kecamatan Kotabumi Utara, Sungkai Selatan, Abung Timur dan Abung Barat.', 5240, 4099, 391, 29, 'Bendung', NULL, NULL, '-', 'SUNGAI WAY ABUNG', 200, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(2, '06.09.11518035740', 'D.I. Jabung', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'SEKAMPUNG', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Bendung Gerak Jabung', 'Sudah', 'Pusat', NULL, NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG TIMUR', 'Pasir Sakti', 'Kedung Ringin', -5.57230000, 105.76811000, NULL, 7288, 7288, 5638, 2554, 'Bendung', NULL, NULL, '-', 'SUNGAI SEKAMPUNG', 0, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(3, '06.09.11518041232', 'D.I. Karya Tani', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'COASTAL', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Free Intake Pasang Surut', 'Sudah', 'Pusat', NULL, NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG TIMUR', 'Pasir Sakti', 'Mekar Sari', -5.49908900, 105.76811000, NULL, 5187, 3733, 3733, 1988, 'Free Intake', NULL, NULL, NULL, 'SUNGAI SEKAMPUNG', 0, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(4, '06.09.11518063772', 'D.I. Pisang', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'SEKAMPUNG', 'Pusat', 'Dalam Kabupaten / Kota', '-', NULL, 'Sudah', 'Pusat', NULL, NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG SELATAN', 'Tersebar**', 'Tersebar**', -5.50309100, 105.66436400, NULL, 10525, 10525, NULL, NULL, 'Free Intake', NULL, NULL, NULL, 'SUNGAI SEKAMPUNG', NULL, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(5, '06.09.11518094256', 'D.I. Way Curup', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'JEPARA', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Intake Tegak Bendung Way Curup', 'Sudah', 'Provinsi', NULL, NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG TIMUR', 'Tersebar**', 'Tersebar**', -5.28035200, 105.73979800, 'Lokasi DI Way Curup di Kabupaten Lampung Timur (Peta Kemendagri, 2020) yang tersebar di 3 Kecamatan, yaitu Kecamatan Labuhan Maringgai, Mataram Baru, dan Way Jepara.', 4689, 4689, 4689, 3792, 'Bendung', NULL, NULL, '-', 'S. WAY CURUP', 45.38, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(6, '06.09.11518094512', 'D.I. Way Jepara', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'JEPARA', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Pintu Intake di Bendungan Way Jepara', 'Sudah', 'Provinsi', 'Proses Pembangunan Daerah Irigasi Way Jepara dimulai dari penyelidikan dan penyusunan suatu rencana Irigasi di Way Jepara oleh Dr. Ir. W.A. Hetzel dan Ir. JA. Buidering Pada Tahun 1940 dan perencanaan pengembangan drainase pada daerah - daerah yang tergenang (rawa - rawa) oleh Ir. Segmand Von Banchet. \n\nTahun 1962 Dr. M. Poerbo Hadiwiyono melakukan penyelidikan geologi tanah dilokasi DAM/Danau Way Jepara. Berdasarkan penyelidikan yang telah dilakukan, Pada tanggal 16 April 1973 dilaksanakan pekerjaan detail design oleh Nippon Koei Co. Ltd dari Jepang dengan biaya pinjaman Technical Assistentance dari OECF Jepang.\n\nPembangunan fisik saluran induk kiri, terowongan dan jaringan irigasi dimulai Pada tanggal 25 April 1973. Pekerjaan dilakukan sampai dengan tahun 1979.\n\nPada tahun 1980 dilanjutkan dengan pembangunan jaringan tersier dan cetak sawah baru sampai dengan tahun 1989. \n\nPada tahun 1990 pada program rehabilitasi jaringan irigasi Way Jepara terdapat pekerjaan tambah yaitu jaringan tersier seluas 1.500 ha.', 'DAS untuk DI ini adalah daerah tangkapan hujan waduk way jepara', 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG TIMUR', 'Tersebar**', 'Tersebar**', -5.20245600, 105.66958600, 'Lokasi DI Way Jepara berada di Kabupaten Lampung Timur (Peta Kemendagri, 2020) yang tersebar di 3 Kecamatan, yaitu Kecamatan Way Jepara, Braja Selebah, dan Labuhan Ratu.', 6651, 6651, 6651, 4167.54, 'Bendungan', 'BENDUNGAN JEPARA', '-', '-', 'BENDUNGAN JEPARA', 130, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(7, '06.09.11518094570', 'D.I. Way Kandis II', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'SEKAMPUNG', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Bendung', 'Tidak/Belum', NULL, 'Bendung 1 buah dan Saluran Primer 4,7 km telah dibangun dari rencana sepanjang 11.9 Km. belum ada Saluran dan bangunan sekunder', NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG SELATAN', 'Jati Agung', 'Karang Anyar', -5.29759500, 105.28840000, NULL, 3500, 3500, NULL, NULL, 'Bendung', NULL, NULL, '-', 'S. WAY KANDIS', NULL, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(8, '06.09.11418095234', 'D.I. Way Pangubuan', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'TULANG BAWANG', 'Pusat', 'Lintas Kabupaten / Kota', '-', 'Intake Tegak', 'Sudah', 'Provinsi', 'Pengembangan Jaringan Irigasi Way Pengubuan dimulai pada tahun 1975 dengan luas areal ± 5.000 ha, dan pengaliran air pertama pada tahun 1978.\n\nPada tahun 1979-1980 dilaksanakan pembangunan jaringan tersier dan pencetakan sawah. Hal ini dimaksudkan agar target pencapaian sawah fungsional dapat lebih cepat terpenuhi.\n\nPemerintah melalui Balai Besar Wilayah Sungai Mesuji Sekampung Kementerian Pekerjaan Umum berusaha untuk mengembalikan fungsi semula jaringan irigasi Way Pengubuan mengingat pentingnya areal irigasi ini bagi masyarakat sekitar. Saat ini fungsi areal irigasi Way Pengubuan sudah berkurang menjadi ± 3.500 ha. Banyak hal yang menyebabkan berkurangnya areal irigasi ini.', NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG TENGAH', 'Tersebar**', 'Tersebar**', -5.01542529, 104.82417986, 'Lokasi DI Way Pangubuan berada di Kabupaten Lampung Tengah (Peta Kemendagri, 2020) dan tersebar di 3 Kecamatan, yaitu Kecamatan Selagai Lingga, Anak Ratu Aji, dan sebagian kecil di Kecamatan Blambangan Pagar Kabupaten Lampung Utara', 5000, 5000, 3609, 2332, 'Bendung', NULL, NULL, '-', 'S. WAY PENGUBUAN', 119.87, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(9, '06.09.11418095420', 'D.I. Way Rarem', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'TULANG BAWANG', 'Pusat', 'Lintas Kabupaten / Kota', '-', 'Intake Tegak', 'Sudah', 'Pusat', 'Pembangunan jaringan irigasi Way Rarem dimaksudkan sebagai bentuk pengelolaan/pemanfaatan potensi sumber air Way Rarem. Pembangunannya dimulai sejak tahun 1972 sampai tahun 1978 untuk pekerjaan SID ( Survey, Investigasi dan Desain ) sedangkan pelaksanaan konstruksi dimulai pada Tahun Anggaran 1978/1979 sampai dengan 1991/1992 sedangkan penyempurnaan prasarana dan sarana jaringan dilakukan pada Tahun Anggaran 1991/1992 sampai 1996/1997', 'Pada D.I. Way Rarem, perhitungan ketersediaan air menggunakan RTOW (Q50%): 13.75 m3/s, Q80 menggunakan 1/3 dari Q50', 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG UTARA', 'Abung Pekurun', 'Tersebar**; Bumi Raharja; Sukoharjo; Surakarta; Sidomukti; Bumi Jaya; Rejo Mulyo; Peraduan Waras', -4.92571900, 104.78511300, 'DI Way Rarem berada di Kabupaten Lampung Utara (hulu) dan Kabupaten Tulang Bawang Barat (Peta Kemendagri, 2020).\n\nDI Way Rarem tersebar di beberapa kecamatan antara lain:\n- Abung Pekurun, Kab. Lampung Utara\n- Abung Kunang, Kab. Lampung Utara\n- Kotabumi Selatan, Kab. Lampung Utara\n- Abung Surakarta, Kab. Lampung Utara\n- Muara Sungkai, Kab. Lampung Utara\n- Abung Timur, Kab. Lampung Utara\n- Abung Semuli, Kab. Lampung Utara\n\n- Tumi Jajar, Kab. Tulang Bawang Barat.\n- Tulang Bawang Udik, Kab. Tulang Bawang Barat.\n- Tulang Bawang Tengah, Kab. Tulang Bawang Barat.', 21110, 22056.2, 21100, 14545.9, 'Bendungan', NULL, '-', '-', 'SUNGAI WAY RAREM', 328, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(10, '06.09.11418095548', 'D.I. Way Sekampung', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'SEKAMPUNG', 'Pusat', 'Lintas Kabupaten / Kota', '-', 'Intake Tegak Bendung Argoguruh', 'Sudah', 'Pusat', 'Sekampung Sistem', 'DI Way Sekampung memiliki Sub DI sebagai berikut:\n- Feeder Canal 1: D.I. Sekampung Bunut, Sekampung Batang Hari, Raman Utara, Batanghari Utara\n- Feeder Canal 2: D.I. Bekri, Punggur Utara, dan Rumbia Barat', 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG TENGAH', 'Tersebar**', 'Tersebar**', -5.17729700, 105.20018900, NULL, 76006, 76006, 58320, 55495, 'Bendung', NULL, NULL, '-', 'SUNGAI SEKAMPUNG', 0, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(11, '06.09.11518095610', 'D.I. Way Seputih', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'SEPUTIH', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Bendung Ajibaru', 'Sudah', 'Provinsi', NULL, NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG TENGAH', 'Tersebar**', 'Tersebar**', -5.01602200, 105.03327100, 'Secara administrasi lokasi Daerah Irigasi Way Seputih berada di Lampung Tengah yang tersebar di beberapa kecamatan yaitu pada kecamatan bandar mataram, seputih mataram, terbanggi besar, gunung sugih, way pengubuan, seputih agung, dan anak tuha', 20201, 20201, 20201, 14569, 'Bendung', NULL, NULL, '-', 'SUNGAI WAY SEPUTIH', 0, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(12, '06.09.11418095954', 'D.I. Way Tebu Sistem', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'SEKAMPUNG', 'Pusat', 'Lintas Kabupaten / Kota', '-', 'Bendung Tebu II; Bendung Tebu III; Bendung Tebu IV', 'Sudah', 'Provinsi', 'DI Way Tebu Sistem terbagi menjadi DI. Way Tebu I dilayani oleh bendung Tebu I yang sudah hancur, awalnya mempunyai layanan seluas 17 ha dan sudah tidak mungkin dikembangkan lagi saat ini. DI. Way Tebu II dilayani oleh bendung Tebu II dibangun tahun 1916 dengan luas potensial 603 ha dan luas fungsional 489 ha. Kemudian DI. Way Tebu IV dibangun tahun 1931 dengan areal potensial 2.660 han dan luas fungsional 2.222 ha. Sumber air irigasi Bendung Tebu IV ini diperoleh dari saluran suplesi dihulunya sepanjang 2,5 km. Saluran suplesi bendung Tebu IV berawal dari Bangunan Bagi KWT.IV yang berada pada ujung saluran primer Way Tebu I-II. Dan pada tahun 1938 dibangunlah DI.Way Tebu III yang dilayani oleh bendung Tebu III dengan luasan layanan potensial sebesar 2.150 ha dan luas fungsional 1.679 ha. Bendung Tebu III juga memperoleh suplesi dari KWT.IV yang dimasukkan ke sungai Way Semah, kemudian dihilir nya air ditangkap oleh bendung Tebu III. Berdasarkan Kepmen PU 390 ketiga daerah irigasi Way Tebu tersebut masih terpisah menjadi tiga yaitu DI. Way Tebu I-II, DI.Way Tebu IV, dan DI. Way Tebu III.', NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. PRINGSEWU', 'Tersebar**', 'Tersebar**', -5.35207400, 104.92176000, 'Way Tebu I dan II di kecamatan Pugung Kabupaten Tanggamus, lokasi desa kajian antara lain : Banjar Agung, Tiuh Memon, Way Jaha dan Rantau Tijang.\nWay Tebu IV di kecamatan Pagelaran kabupaten Pringsewu, lokasi desa kajian antrara lain : Lugusari, Pagelaran, Panutan, Bumi Ratu, Sukawangi, Way Ngisom, Sukaratu, Patoman, Gumukmas, dan Karangsari. \nWay Tebu III di kecamatan Pringsewu Kabupaten Pringsewu, lokasi desa kajian antara lain: Bumi Ayu, Padang Bulan, Fajar Esuk, Bumi Arum, Rejosari, Podosari, Podorejo, Pringsewu, Podomoro, Pringkumpul, Pringombo, Sidoharjo dan di desa Jogjakarta kecamatan Gadingrejo kabupaten Pringsewu.', 4188, 4188, 4188, 1951.32, 'Bendung', NULL, NULL, '-', 'S. WAY TEBU', 0, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(13, '06.09.11518096060', 'D.I. Way Tulung Mas', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'TULANG BAWANG', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Intake Tegak', 'Sudah', 'Provinsi', 'DI Tulung Mas berada di Kabupaten Lampung Utara', 'STUDI / PERENCANAAN YANG TELAH DILAKSANAKAN:\n\n- Survey Geologi, tahun 1978 s/d 1979\n- Survey Pengukuran dan perencanaan, tahun 1979 s/d 1980.\n- Penelitian Geologi dan Model Test, tahun 1980 s/d 1981.\n- Perencanaan Tesier / geologi, tahun 1985 s/d 1986\n- Perencanaan jaringan Tersier 1988 s/d 1989.\n- Studiy Evaluasi Kinerja Jaringan dan Bangunan Air pada\n- DI Way Tulung, tahun 2006 oleh PT. Pratama Kurnia Pratama. Penelitian', 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG UTARA', 'Sungkai Selatan', 'Tersebar**; Banjar Wangi; Iso Rejo; Margo Rejo; Wono Marto; Sawo Jajar; Sidodadi; Bumi Ratu', -4.78690730, 104.77473855, 'Lokasi DI Way Tulung Mas berada di Kabupaten Lampung Utara (Peta Kemendagri, 2020) dan tersebar di 3 Kecamatan, yaitu Kecamatan Sungkai Selatan, Kecamatan Kotabumi Utara, dan Kecamatan Bungamayang.', 3200, 3483.28, 3483.28, 1019.12, 'Bendung', NULL, NULL, '-', 'SUNGAI WAY TULUNGMAS', 75.158, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(14, '06.09.11518096096', 'D.I. Way Umpu', 'Irigasi Permukaan', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'TULANG BAWANG', 'Pusat', 'Dalam Kabupaten / Kota', '-', 'Intake Tegak', 'Sudah', 'Pusat', 'DI Way Umpu dibangun pada tahun anggaran 1976–1977 dan 1980–1981 menggunakan sumber dana APBN dan Loan OECF dengan luas layanan 7.500 ha.', 'Air untuk Daerah Irigasi Way Umpu bersumber dari Bendung Way Umpu dengan dibantu suplesi dari Bendung Way Besai. Untuk meningkatkan Luas fungsi serta Intensitas Tanam, pada Tahun 2016 dibangun saluran suplesi dari Bendung Way Besai ke saluran induk Neki.\n\nData Hidrologi yang tercantum dalam WRDC adalah di DTH Bendung Way Umpu. Untuh DTH Way Besai (Suplesi) adalah:\nCurah hujan rata-rata tahunan: 2992.67 mm\nQ80: 16.88 m3/s', 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. WAY KANAN', 'Tersebar**', 'Tersebar**; Bali Sadhar Tengah; Pasar Banjit; Rantau Jaya; Rantau Temiang; Simpang Asam; Sumber Baru; Banjar Sari; Banjar Setia; Gedung Rejo', -4.83191029, 104.47078999, 'Lokasi DI Way Umpu berada di Kabupaten Way Kanan (Peta Kemendagri, 2020) dan tersebar di 3 Kecamatan, yaitu Kecamatan Banjir, Kecamatan Baradatu, dan Kecamatan Kasui.', 7500, 7269.83, 7269.83, 3285.5, 'Bendung', NULL, NULL, '-', 'SUNGAI WAY UMPU', 210, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(15, '06.09.31418111066', 'D.I.R. Rawa Jitu', 'Rawa', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'MESUJI', 'Pusat', 'Lintas Kabupaten / Kota', '2025', NULL, 'Sudah', 'Pusat', 'Rawa Mesuji Tulang Bawang (Rawa Jitu) Unit I, II dan IV dengan luas 20.000 Ha mulai dikembangkan tahun anggaran 1984/1985 dan selesai pelaksanaan tahun anggaran 1990/1991', NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. MESUJI', 'Rawa Jitu Utara', 'Sidang Sido Rahayu; Hargo Rejo; Hargo Mulyo; Medasari; Gedung Karya Jitu; Telogo Rejo; Sidang Bandar Anom; Panggung Jaya; Sidang Kurnia Agung; Panggung Rejo; Gedung Meneng Baru; Sidang Muara Jaya; Sidang Makmur; Bumi Dipasena Makmur; Sidang Gunung Tiga; Sungai Sidang; Karya Cipta Abadi; Bumi Dipasena Sejahtera; Bumi Dipasena Mulya', -4.26483900, 105.67196200, 'Sumber Peta: BIG, 2022', 17515, 17176.2, 14764.9, 14764.9, NULL, NULL, '-', NULL, NULL, NULL, 'Pasang Surut', 'Drainase', '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(16, '06.09.31518111074', 'D.I.R. Rawa Mesuji Atas', 'Rawa', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'MESUJI', 'Pusat', 'Dalam Kabupaten / Kota', '2025', NULL, 'Sudah', 'Pusat', NULL, NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. MESUJI', 'Tersebar**', 'Tersebar**; Sungai Buaya; Tebing Karya Mandiri; Pangkal Mas Jaya; Pangkal Mas Mulya; Muara Mas; Muara Asri; Tanjung Mas Rejo; Tanjung Mas Jaya; Tanjung Mas Makmur; Tirta Laga; Tanjung Serayan; Sumber Makmur; Mulya Sari; Suka Maju', -3.89359200, 105.55657800, 'Lokasi DIR Mesuji Atas di Kabupaten Mesuji (Peta Kemendagri, 2020) yang tersebar di 3 Kecamatan, yaitu Kecamatan Mesuji, Mesuji Timur dan Rawa Jitu Utara.', 16328, 16980, 16980, 7363, NULL, NULL, '-', NULL, NULL, NULL, 'Pasang Surut', 'Drainase', '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(17, '06.09.31518111086', 'D.I.R. Rawa Pitu', 'Rawa', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'MESUJI-TULANG BAWANG', 'TULANG BAWANG', 'Pusat', 'Dalam Kabupaten / Kota', '2025', NULL, 'Sudah', 'Pusat', 'Pengambilan free intake dari Sungai Way Pidada dan Way Tulang Bawang', NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. TULANG BAWANG', 'Rawa Pitu', 'Tersebar**', -4.25723300, 105.60246900, NULL, 10529, 10529, 10529, 8198.83, NULL, NULL, '-', NULL, NULL, NULL, 'Pasang Surut', 'Drainase', '2026-07-06 08:20:38', '2026-07-06 08:20:38'),
(18, '06.09.31518112214', 'D.I.R. Tambak Rakyat', 'Tambak', '-', 'Sesuai Permen 2014', 'BALAI BESAR WILAYAH SUNGAI MESUJI SEKAMPUNG', 'SEPUTIH-SEKAMPUNG', 'SEKAMPUNG', 'Pusat', 'Dalam Kabupaten / Kota', '-', NULL, 'Tidak/Belum', NULL, NULL, NULL, 'Tidak Terkunci', 'Tidak Terverifikasi', 'LAMPUNG', 'KAB. LAMPUNG SELATAN', 'Ketapang', 'Berundung', -5.58577200, 105.81108900, 'Lokasi DI Tambak Rakyat di Kabupaten Lampung Selatan (Peta Kemendagri, 2020) tersebar di 2 Kecamatan, yaitu Kecamatan Sragi dan Kecamatan Ketapang. DI Tambak Rakyat ini tersebar di 3 desa, antara lain Bandar Agung, Berundung, dan Pematang Pasir.', 4000, 4000, 4000, 4000, 'Free Intake', NULL, NULL, '0', NULL, 0, NULL, NULL, '2026-07-06 08:20:38', '2026-07-06 08:20:38');

