--
-- Struktur dari tabel `data_manual`
--

CREATE TABLE `data_manual` (
  `id_manual` int NOT NULL,
  `id_pos` int NOT NULL COMMENT 'FK ke master_pos',
  `id_user` int DEFAULT NULL COMMENT 'FK ke users (petugas yang input)',
  `tanggal_input` date NOT NULL COMMENT 'Tanggal pengukuran (dipilih petugas)',
  `rain` float DEFAULT NULL COMMENT 'Curah hujan (mm) - diisi jika PCH atau Bendungan',
  `wlevel` float DEFAULT NULL COMMENT 'Tinggi muka air (m/cm) - diisi jika PDA atau Bendungan',
  `keterangan` varchar(255) DEFAULT NULL COMMENT 'Keterangan tambahan',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Jam input otomatis',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Waktu update terakhir'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Data input manual oleh petugas pos';

