CREATE TABLE `data_pengaman_pantai` (
  `id_pengaman` int NOT NULL,
  `kode_integrasi` varchar(50) DEFAULT NULL COMMENT 'Kode Integrasi dari Excel',
  `nama_aset` varchar(200) NOT NULL COMMENT 'Nama aset',
  `jenis_bangunan` varchar(50) DEFAULT NULL COMMENT 'Jenis Bangunan (JETTY, REVETMENT, dll)',
  `sungai` varchar(100) DEFAULT NULL COMMENT 'Daerah Aliran Sungai',
  `wilayah_sungai` varchar(100) DEFAULT NULL COMMENT 'Wilayah Sungai',
  `lat_awal` decimal(11,8) DEFAULT NULL COMMENT 'Latitude titik awal',
  `lng_awal` decimal(11,8) DEFAULT NULL COMMENT 'Longitude titik awal',
  `lat_akhir` decimal(11,8) DEFAULT NULL COMMENT 'Latitude titik akhir',
  `lng_akhir` decimal(11,8) DEFAULT NULL COMMENT 'Longitude titik akhir',
  `panjang` float DEFAULT NULL COMMENT 'Panjang bangunan (m)',
  `elevasi_puncak` float DEFAULT NULL COMMENT 'Elevasi puncak (mdpl)',
  `lebar_puncak` float DEFAULT NULL COMMENT 'Lebar puncak (m)',
  `tahun_dibangun` year DEFAULT NULL COMMENT 'Tahun selesai pembangunan',
  `kabupaten_kota` varchar(100) DEFAULT NULL COMMENT 'Kabupaten/Kota',
  `kecamatan` varchar(100) DEFAULT NULL COMMENT 'Kecamatan',
  `kelurahan` varchar(100) DEFAULT NULL COMMENT 'Kelurahan/Desa',
  `manfaat` text COMMENT 'Manfaat bangunan',
  `keterangan` text COMMENT 'Keterangan tambahan',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Data infrastruktur pengaman pantai';

