--
-- Struktur dari tabel `data_pengendali_sedimen`
--

CREATE TABLE `data_pengendali_sedimen` (
  `id_sedimen` int NOT NULL,
  `kode_integrasi` varchar(50) DEFAULT NULL COMMENT 'Kode Integrasi dari Excel',
  `nama_aset` varchar(200) NOT NULL COMMENT 'Nama aset',
  `jenis_bangunan` varchar(50) DEFAULT NULL COMMENT 'Jenis Pengendali Sedimen (Cekdam, Sabodam, dll)',
  `sungai` varchar(100) DEFAULT NULL COMMENT 'Nama Sungai',
  `daerah_aliran_sungai` varchar(100) DEFAULT NULL COMMENT 'DAS',
  `wilayah_sungai` varchar(100) DEFAULT NULL COMMENT 'Wilayah Sungai',
  `lat` decimal(11,8) DEFAULT NULL COMMENT 'Latitude',
  `lng` decimal(11,8) DEFAULT NULL COMMENT 'Longitude',
  `daya_tampung` float DEFAULT NULL COMMENT 'Daya Tampung (m3)',
  `panjang` float DEFAULT NULL COMMENT 'Panjang (m)',
  `lebar` float DEFAULT NULL COMMENT 'Lebar (m)',
  `tinggi` float DEFAULT NULL COMMENT 'Tinggi (m)',
  `tahun_dibangun` year DEFAULT NULL COMMENT 'Tahun selesai pembangunan',
  `kabupaten_kota` varchar(100) DEFAULT NULL COMMENT 'Kabupaten/Kota',
  `kecamatan` varchar(100) DEFAULT NULL COMMENT 'Kecamatan',
  `kelurahan` varchar(100) DEFAULT NULL COMMENT 'Kelurahan/Desa',
  `jenis_material` varchar(100) DEFAULT NULL COMMENT 'Jenis & Bahan Sabodam',
  `keterangan` text COMMENT 'Keterangan tambahan',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Data infrastruktur pengendali sedimen (check dam/sabodam)';

