--
-- Struktur dari tabel `master_pos`
--

CREATE TABLE `master_pos` (
  `id_pos` int NOT NULL,
  `nomor_pos` varchar(50) DEFAULT NULL,
  `nama_pos` varchar(100) NOT NULL,
  `tipe_pos` enum('PCH','PDA') NOT NULL,
  `sungai` varchar(100) DEFAULT NULL,
  `wilayah_sungai` varchar(100) DEFAULT NULL COMMENT 'Wilayah Sungai',
  `lat` decimal(11,8) DEFAULT NULL,
  `lng` decimal(11,8) DEFAULT NULL,
  `device_id_telemetry` varchar(100) DEFAULT NULL,
  `is_bendungan` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=Pos Biasa, 1=Bendungan',
  `is_bendung` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=Pos Biasa/Bendungan, 1=Bendung',
  `jenis_aset` enum('bendungan','bendung','embung','pch','pda') DEFAULT NULL COMMENT 'Jenis aset untuk membedakan jenis pos',
  `nwl` float DEFAULT NULL COMMENT 'Normal Water Level (m)',
  `nwl_volume` float DEFAULT NULL COMMENT 'Volume NWL (jt.m³)',
  `nwl_luas` float DEFAULT NULL COMMENT 'Luas NWL (km²)',
  `siaga1` float DEFAULT '0',
  `siaga2` float DEFAULT '0',
  `siaga3` float DEFAULT '0',
  `siaga4` float DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `petugas_id` int DEFAULT NULL,
  `admin_id` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

